import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { attendanceService } from '../../services/attendanceService';
import '../../styles/table.scss';

const AttendanceList = ({ onNavigateReport, onNavigateWorkAnniversary }) => {
  const navigate = useNavigate();
  const [attendanceData, setAttendanceData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedMonth, setSelectedMonth] = useState('2024-09');
  const [selectedDate, setSelectedDate] = useState('2024-09-01');

  useEffect(() => {
    fetchData();
  }, [selectedMonth]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const res = await attendanceService.getSummary(selectedMonth);
      if (res.success) {
        setAttendanceData(res.data);
      }
    } catch (error) {
      console.error("Error fetching data", error);
    } finally {
      setLoading(false);
    }
  };

  const stats = useMemo(() => {
    return {
      total: attendanceData.length,
      present: attendanceData.filter(r => r.PresentDays > 0).length,
      absent: attendanceData.filter(r => r.AbsentDays > 0).length,
      leave: attendanceData.filter(r => r.LeaveDays > 0).length
    };
  }, [attendanceData]);

  return (
    <div className="attendance-page animate-fade-in" style={{ padding: '24px', background: '#f8fafc' }}>
      <div className="header-actions" style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '24px' }}>
        <div className="search-bar" style={{ position: 'relative', width: '400px' }}>
          <input type="text" placeholder="Tìm kiếm nhân viên..." style={{ width: '100%', padding: '12px 40px', borderRadius: '12px', border: '1px solid #e2e8f0' }} />
          <span style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)' }}>🔍</span>
        </div>
        <div style={{ display: 'flex', gap: '12px' }}>
          <select value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} style={{ padding: '10px', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
            <option value="2024-09">Tháng 9, 2024</option>
            <option value="2026-05">Tháng 5, 2026</option>
          </select>
          <button className="primary-btn" onClick={onNavigateWorkAnniversary} style={{ background: '#1e293b', color: '#fff', padding: '10px 20px', borderRadius: '8px', border: 'none', cursor: 'pointer' }}>
            Thông báo kỷ niệm ngày làm việc
          </button>
        </div>
      </div>

      <div className="stats-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '24px' }}>
        <div className="stat-card" style={{ background: '#fff', padding: '20px', borderRadius: '16px', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
          <div style={{ color: '#64748b', fontSize: '14px' }}>Tổng số nhân viên</div>
          <div style={{ fontSize: '24px', fontWeight: 'bold' }}>{stats.total}</div>
        </div>
        <div className="stat-card" style={{ background: '#fff', padding: '20px', borderRadius: '16px', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
          <div style={{ color: '#10b981', fontSize: '14px' }}>Hiện tại</div>
          <div style={{ fontSize: '24px', fontWeight: 'bold' }}>{stats.present}</div>
        </div>
        <div className="stat-card" style={{ background: '#fff', padding: '20px', borderRadius: '16px', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
          <div style={{ color: '#ef4444', fontSize: '14px' }}>Vắng mặt</div>
          <div style={{ fontSize: '24px', fontWeight: 'bold' }}>{stats.absent}</div>
        </div>
        <div className="stat-card" style={{ background: '#fff', padding: '20px', borderRadius: '16px', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
          <div style={{ color: '#f59e0b', fontSize: '14px' }}>Muộn / Nghỉ</div>
          <div style={{ fontSize: '24px', fontWeight: 'bold' }}>{stats.leave}</div>
        </div>
      </div>

      <div className="data-panel" style={{ background: '#fff', borderRadius: '16px', padding: '24px', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px' }}>
          <h3>Nhật ký chấm công nhân viên</h3>
          <button className="outline-btn" style={{ border: '1px solid #e2e8f0', background: 'none', padding: '8px 16px', borderRadius: '6px' }}>Hiển thị 10 trong số {stats.total}</button>
        </div>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ textAlign: 'left', borderBottom: '1px solid #f1f5f9' }}>
              <th style={{ padding: '12px' }}><input type="checkbox" /></th>
              <th style={{ padding: '12px' }}>Mã nhân viên</th>
              <th style={{ padding: '12px' }}>Họ và tên / Liên hệ</th>
              <th style={{ padding: '12px' }}>Số điện thoại</th>
              <th style={{ padding: '12px' }}>Phòng ban</th>
              <th style={{ padding: '12px' }}>Chức vụ</th>
              <th style={{ padding: '12px' }}>Tình trạng</th>
            </tr>
          </thead>
          <tbody>
            {attendanceData.map(row => (
              <tr key={row.EmployeeID} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={{ padding: '12px' }}><input type="checkbox" /></td>
                <td style={{ padding: '12px' }}>EMP-{String(row.EmployeeID).padStart(5, '0')}</td>
                <td style={{ padding: '12px' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                    <div style={{ width: '32px', height: '32px', borderRadius: '50%', background: '#e2e8f0', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{row.FullName[0]}</div>
                    <div>
                      <div>{row.FullName}</div>
                      <div style={{ fontSize: '12px', color: '#94a3b8' }}>{row.Email}</div>
                    </div>
                  </div>
                </td>
                <td style={{ padding: '12px' }}>{row.PhoneNumber}</td>
                <td style={{ padding: '12px' }}>{row.DepartmentName}</td>
                <td style={{ padding: '12px' }}>{row.PositionName}</td>
                <td style={{ padding: '12px' }}>
                  <span style={{ padding: '4px 12px', borderRadius: '20px', fontSize: '12px', background: row.PresentDays > 0 ? '#dcfce7' : '#fee2e2', color: row.PresentDays > 0 ? '#10b981' : '#ef4444' }}>
                    {row.PresentDays > 0 ? 'Có mặt' : 'Vắng mặt'}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        <div style={{ marginTop: '20px', textAlign: 'right' }}>
          <button className="primary-btn" onClick={onNavigateReport} style={{ background: '#1e293b', color: '#fff', padding: '10px 20px', borderRadius: '8px', border: 'none', cursor: 'pointer' }}>
            Tạo báo cáo chi tiết
          </button>
        </div>
      </div>
    </div>
  );
};

export default AttendanceList;
